// beats cross beats onshore), then size. The winner goes to Ketut, boards on the roof.
const S = $('Kook settings').first().json;
const breaks = $('The breaks').all().map(i => i.json);
const R = $('Surfline: rating (each break)').all(), SU = $('Surfline: surf (each break)').all(), WI = $('Surfline: wind (each break)').all();
const today = balToday();
const RATE = { VERY_POOR: 'very poor', POOR: 'poor', POOR_TO_FAIR: 'poor to fair', FAIR: 'fair', FAIR_TO_GOOD: 'fair to good', GOOD: 'good', VERY_GOOD: 'very good', GOOD_TO_EPIC: 'good to epic', EPIC: 'EPIC' };
function at6(arr) {                       // today's 6am slot, else the first slot of the feed
  if (!arr || !arr.length) return null;
  const local = x => new Date((x.timestamp + (x.utcOffset || 8) * 3600) * 1000);
  return arr.find(x => local(x).toISOString().slice(0, 10) === today && local(x).getUTCHours() === 6) ||
         arr.find(x => local(x).getUTCHours() >= 6) || arr[0];
}
const scored = breaks.map((b, i) => {
  const r = at6(((load(R[i] && R[i].json) || {}).data || {}).rating);
  const s = at6(((load(SU[i] && SU[i].json) || {}).data || {}).surf);
  const w = at6(((load(WI[i] && WI[i].json) || {}).data || {}).wind);
  if (!r || !s || !w) return { ...b, ok: false };
  const wind = w.directionType === 'Offshore' ? 6 : w.directionType === 'Cross-shore' ? 1 : -6;
  // size: closest to the crew's ideal wave (IDEAL_FT) wins, so 6-8ft beats both 4-6 and 10-12
  const size = -Math.abs((s.surf.min + s.surf.max) / 2 - (S.IDEAL_FT || 6)) * 1.5;
  const score = (r.rating.value || 0) * 10 + wind - (w.speed || 0) * 0.4 + size;
  return { ...b, ok: true, score: Math.round(score * 10) / 10, rating: RATE[r.rating.key] || r.rating.key,
           min: s.surf.min, max: s.surf.max, windType: w.directionType, windKts: Math.round(w.speed || 0) };
}).filter(b => b.ok).sort((a, b) => b.score - a.score);
if (!scored.length) return [{ json: { none: true, group: '🌅 Surfline did not answer this morning. Kook will check again at 6:30.', ketut: '' } }];
const top = scored[0];
const medals = ['🥇', '🥈', '🥉', '4.', '5.'];
const board = scored.map((b, k) => `${medals[k] || (k + 1) + '.'} ${esc(b.name)}: ${b.min}-${b.max}ft, ${b.windType.toLowerCase()} ${b.windKts}kts, ${b.rating}`).join('\n');
return [{ json: {
  pick: top.name,
  group: `🌅 <b>6am surf check</b>\n${board}\n\n<b>Today: ${esc(top.name)}.</b> Ketut's out the front at 6:30 with the boards on the roof.`,
  ketut: `Pagi Ketut! 🌅 ${top.name} today. Pick up 6:30 at the villa please, ${S.CREW.length} boards on the roof. Terima kasih!`,
} }];
